import json,sqlite3
live='/private/tmp/jobbot-verify-CHG-39-r13.SMxu0a/live.sqlite3'
cache='/private/tmp/jobbot-verify-CHG-39-r13.SMxu0a/live-observation-cache.sqlite3'
forbidden={'cookie','cookies','credential','credentials','password','token','access_token','refresh_token','bridge_token','session','session_id','captcha','captcha_material','browser_profile','profile_data'}
def walk(v, path=''):
    bad=[]
    if isinstance(v,dict):
        for k,x in v.items():
            kl=str(k).casefold()
            if kl in forbidden or any(m in kl for m in ('cookie','password','secret','token')): bad.append(path+str(k))
            bad += walk(x,path+str(k)+'.')
    elif isinstance(v,list):
        for i,x in enumerate(v): bad += walk(x,path+str(i)+'.')
    return bad
with sqlite3.connect(cache) as c:
    c.row_factory=sqlite3.Row
    rows=c.execute('SELECT platform,normalized_card_json,detail_job_json,detail_provenance_json FROM crawl_observations').fetchall()
    bad=[]
    for row in rows:
        for key in ('normalized_card_json','detail_job_json','detail_provenance_json'):
            try: bad += [f\"{row['platform']}:{key}:{x}\" for x in walk(json.loads(row[key] or '{}'))]
            except Exception as exc: bad.append(f'{row[\"platform\"]}:{key}:invalid_json')
    print('cache_rows',len(rows),'cache_forbidden_key_hits',len(bad),'cache_forbidden_samples',bad[:5])
with sqlite3.connect(live) as c:
    c.row_factory=sqlite3.Row
    rows=c.execute(\"SELECT evidence_provenance_json FROM jobs WHERE job_id IN (SELECT canonical_job_id FROM search_task_results WHERE browser_run_id=1 AND canonical_job_id IS NOT NULL)\").fetchall()
    modes=[]
    for row in rows:
        try:
            v=json.loads(row[0] or '{}'); d=v.get('detail_acquisition') if isinstance(v,dict) else {}
            modes.append(d.get('mode','') if isinstance(d,dict) else '')
        except Exception: modes.append('invalid')
    print('authoritative_jobs',len(rows),'cache_mode_authoritative_jobs',sum(x=='cache' for x in modes),'search_pane_mode_jobs',sum(x=='search_pane' for x in modes),'other_modes',sorted({x for x in modes if x not in ('cache','search_pane')}))
    print('duplicate_canonical_ids',c.execute(\"SELECT COUNT(*)-COUNT(DISTINCT canonical_job_id) FROM search_task_results WHERE browser_run_id=1 AND canonical_job_id IS NOT NULL\").fetchone()[0])
    print('integrity',c.execute('PRAGMA integrity_check').fetchone()[0])
PY"
